// 8-week zoom-out: volume table, CTL, cadence, grades, swim count, recovery.
const athlete = $('Get Athlete').first().json;
const wrapped = $('Get Review Sessions').first().json;
const sessions = Array.isArray(wrapped.sessions) ? wrapped.sessions : [];
const wresp = $input.first().json;
const wellness = Array.isArray(wresp.body) ? wresp.body : [];

const normSport = s => { const sp = (s || '').toLowerCase(); if (sp.includes('swim')) return 'Swim'; if (sp.includes('run')) return 'Run'; if (sp.includes('ride') || sp.includes('bike') || sp.includes('cycl') || sp.includes('virtual')) return 'Ride'; return 'Workout'; };

// Volume by ISO week
const byWeek = {};
for (const s of sessions) {
  if (!s.date) continue;
  const wk = DateTime.fromISO(s.date).startOf('week').toFormat('yyyy-MM-dd');
  byWeek[wk] = byWeek[wk] || { total: 0, Swim: 0, Run: 0, Ride: 0, Workout: 0, n: 0 };
  const b = byWeek[wk];
  b.total += (s.duration_min || 0); b[normSport(s.sport)] += (s.duration_min || 0); b.n++;
}
const weeks = Object.keys(byWeek).sort();
const h = m => (m / 60).toFixed(1);
const volLines = weeks.map(wk => 'Wk of ' + wk.slice(5) + ': ' + h(byWeek[wk].total) + 'h (' + byWeek[wk].n + ' sessions) — swim ' + h(byWeek[wk].Swim) + ' / bike ' + h(byWeek[wk].Ride) + ' / run ' + h(byWeek[wk].Run) + ' / other ' + h(byWeek[wk].Workout));

// CTL trajectory
const withCtl = sessions.filter(s => s.ctl != null && s.date).sort((a, b) => (a.date < b.date ? -1 : 1));
const ctlLine = withCtl.length ? 'CTL: ' + Math.round(withCtl[0].ctl) + ' → ' + Math.round(withCtl[withCtl.length - 1].ctl) + ' over ' + weeks.length + ' weeks' : 'No CTL data';

// Run cadence (avg_cadence is half-spm — ×2), last 28d vs prior, duration-weighted
const cut28 = DateTime.now().minus({ days: 28 }).toFormat('yyyy-MM-dd');
const runs = sessions.filter(s => normSport(s.sport) === 'Run' && s.avg_cadence > 0 && (s.duration_min || 0) >= 10);
const wAvg = arr => { const d = arr.reduce((t, s) => t + s.duration_min, 0); return d ? arr.reduce((t, s) => t + s.avg_cadence * 2 * s.duration_min, 0) / d : null; };
const cadNow = wAvg(runs.filter(s => (s.date || '') >= cut28)), cadPrior = wAvg(runs.filter(s => (s.date || '') < cut28));
const cadLine = cadNow ? 'Run cadence: ' + Math.round(cadNow) + ' spm last 28d' + (cadPrior ? ' (prior 28d: ' + Math.round(cadPrior) + ')' : '') + ' — target 175-180' : 'No run cadence data';

// Grades
const graded = sessions.filter(s => s.grade);
const gd = {}; graded.forEach(s => { gd[s.grade] = (gd[s.grade] || 0) + 1; });
const gradeLine = graded.length ? 'Session grades: ' + ['A', 'B', 'C', 'F'].filter(g => gd[g]).map(g => g + '×' + gd[g]).join(' · ') : 'No graded sessions';

// Swim frequency vs 2/wk target
const swimN = sessions.filter(s => normSport(s.sport) === 'Swim').length;
const swimLine = 'Swim sessions: ' + swimN + ' across ' + weeks.length + ' weeks (target 2/wk)';

// Recovery: sleep + HRV, last 28d vs prior
const wvalid = wellness.filter(d => d && /^\d{4}-\d{2}-\d{2}$/.test(d.id || ''));
const wrecent = wvalid.filter(d => d.id >= cut28), wprior = wvalid.filter(d => d.id < cut28);
const avg = (arr, f) => { const v = arr.map(d => d[f]).filter(x => x != null); return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null; };
const sl = avg(wrecent, 'sleepSecs'), slp = avg(wprior, 'sleepSecs'), hv = avg(wrecent, 'hrv'), hvp = avg(wprior, 'hrv');
const fmtH = s => s == null ? '?' : Math.floor(s / 3600) + 'h' + String(Math.round((s % 3600) / 60)).padStart(2, '0');
const wellLine = (sl != null || hv != null) ? 'Recovery: sleep ' + fmtH(sl) + '/night last 28d (prior ' + fmtH(slp) + ') · HRV ' + (hv ? Math.round(hv) : '?') + ' (prior ' + (hvp ? Math.round(hvp) : '?') + ')' : 'No wellness data';

const Wr = Math.max(0, Math.ceil(DateTime.fromISO(athlete['Race Date']).diff(DateTime.now(), 'weeks').weeks));
const reviewContext = ['VOLUME BY WEEK:', ...volLines, '', ctlLine, cadLine, gradeLine, swimLine, wellLine].join('\n');
return [{ json: { ...athlete, reviewContext, weeks_to_race: Wr, monthName: DateTime.now().toFormat('LLLL yyyy') } }];

